import { test, expect } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

test.describe('Звонок 101 с экрана «עזרה דחופה»', () => {
  test('Окно «לחייג למד״א 101?» → «חיוג ל-101» открывает tel:101 без сообщения об ошибке #1273694f @iphone @prod-safe', async ({ page }) => {
    const dialogs: string[] = [];
    page.on('dialog', async (dialog) => {
      dialogs.push(dialog.message());
      await dialog.dismiss();
    });

    // 1. Поставить шпион tel: (сайт уходит на tel: через window.location = 'tel:101'; Linking.openURL в react-native-web).
    // Навигация на tel: перехватывается через Navigation API и отменяется, чтобы звонок не ушёл.
    await page.addInitScript(() => {
      const w = window as any;
      w.__telCalls = [];
      w.navigation?.addEventListener('navigate', (e: any) => {
        if (String(e.destination.url).startsWith('tel:')) {
          w.__telCalls.push(e.destination.url);
          if (e.cancelable) e.preventDefault();
        }
      });
      const originalOpen = window.open;
      window.open = function (url?: string | URL, ...rest: any[]) {
        if (String(url).startsWith('tel:')) {
          w.__telCalls.push(String(url));
          return null;
        }
        return (originalOpen as any).call(this, url, ...rest);
      } as typeof window.open;
      document.addEventListener(
        'click',
        (e) => {
          const a = (e.target as Element | null)?.closest?.('a[href^="tel:"]') as HTMLAnchorElement | null;
          if (a) {
            w.__telCalls.push(a.href);
            e.preventDefault();
          }
        },
        true,
      );
    });
    await page.goto('/emergency');

    // 2. Нажать «חיוג למד״א 101».
    await page.getByRole('button', { name: 'חיוג למד״א 101' }).click();

    // 3. В окне «לחייג למד״א 101?» нажать «חיוג ל-101».
    await expect(page.getByRole('heading', { name: 'לחייג למד״א 101?' })).toBeVisible();
    const confirmButton = page.getByRole('button', { name: 'חיוג ל-101' });
    await expect(confirmButton).toBeVisible();
    await confirmButton.click();

    // Ожидаемое: ровно одна попытка открыть tel:101, сообщения об ошибке и нативного диалога нет.
    await expect.poll(() => page.evaluate(() => (window as any).__telCalls)).toEqual(['tel:101']);
    await expect(page.getByText('לא ניתן לחייג מהמכשיר הזה')).toHaveCount(0);
    expect(dialogs).toEqual([]);
  });
});
